<script setup lang="ts">
import type { Product,CartLine } from '@ellas/shared';
const route=useRoute();const selection=useSelection();
const {data:product,error}=await useFetch<Product>(`/api/catalog/products/${route.params.slug}`);
if(error.value || !product.value) throw createError({statusCode:404,statusMessage:'Prenda no encontrada'});
useSeo(`${product.value.name} · ${product.value.reference}`,product.value.description);
const selectedColors=ref<string[]>([product.value.colors[0]?.code || '']); const quantities=reactive<Record<string,number>>({}); const added=ref(0);const validation=ref('');
const chosen=computed(()=>product.value?.colors.filter(c=>selectedColors.value.includes(c.code)) || []);
const total=computed(()=>Object.values(quantities).reduce((sum,value)=>sum+(Number.isFinite(value)?value:0),0));
function toggle(color:string){added.value=0; if(selectedColors.value.includes(color)){selectedColors.value=selectedColors.value.filter(c=>c!==color);for(const key of Object.keys(quantities)) if(key.startsWith(color+':')) delete quantities[key];}else selectedColors.value.push(color);}
function add(){if(!product.value)return;validation.value='';const lines:CartLine[]=[];for(const color of chosen.value)for(const size of color.sizes){const quantity=quantities[`${color.code}:${size}`] || 0;if(!Number.isInteger(quantity)||quantity<0||quantity>10000){validation.value='Usa cantidades enteras entre 0 y 10.000.';return;}if(quantity)lines.push({reference:product.value.reference,name:product.value.name,color:color.code,colorName:color.name,size,quantity,image:product.value.imageSmall});}if(!lines.length){validation.value='Indica la cantidad de al menos una talla.';return;}selection.add(lines);added.value=lines.reduce((sum,l)=>sum+l.quantity,0);for(const key of Object.keys(quantities))delete quantities[key];}
const jsonLd=computed(()=>({'@context':'https://schema.org','@type':'Product',name:product.value?.name,sku:product.value?.reference,description:product.value?.description,image:new URL(product.value?.image || '/',useRuntimeConfig().public.appUrl).href,brand:{'@type':'Brand',name:'JHK T-Shirt'},material:product.value?.composition}));
useHead({script:[{type:'application/ld+json',innerHTML:JSON.stringify(jsonLd.value).replace(/</g,'\\u003c')}]});
</script>
<template><div v-if="product" class="container product-page"><div class="breadcrumb"><NuxtLink to="/">Inicio</NuxtLink><span>/</span><NuxtLink to="/catalogo">Catálogo</NuxtLink><span>/</span><span>{{product.reference}}</span></div><div class="product-detail"><div class="product-gallery"><div class="product-main-photo"><img :src="product.image" :alt="product.name" :width="product.imageWidth" :height="product.imageHeight" fetchpriority="high" /><span class="photo-caption">JHK / {{product.collection}} / 2026</span></div><div class="product-promise"><AppIcon name="CheckCircle2" :size="18" /><span>Fotografía y especificaciones del catálogo JHK 2026.</span></div></div><div class="product-content"><div class="product-heading"><span class="eyebrow">{{product.collection}} <span class="separator">/</span> {{product.audience}}</span><span class="ref-label">REF. {{product.reference}}</span></div><h1>{{product.name}}</h1><p class="product-description">{{product.description}}</p><div class="product-price">Precio bajo presupuesto <span>Lo preparamos a la medida de tu equipo.</span></div><div class="product-specs"><span><b>Tejido</b>{{product.composition || 'Consultar ficha original'}}</span><span v-if="product.weight"><b>Gramaje</b>{{product.weight}} g/m² aprox.</span><span><b>Opciones</b>{{product.colors.length}} colores · {{product.sizes.length}} tallas</span></div><div class="configurator"><h2><span class="step-circle">1</span> Elige uno o varios colores</h2><div class="color-picker"><button v-for="color in product.colors" :key="color.code" :class="{selected:selectedColors.includes(color.code)}" :aria-pressed="selectedColors.includes(color.code)" :aria-label="`${color.name} (${color.code})`" :title="`${color.name} (${color.code})`" @click="toggle(color.code)"><span :style="{ background: color.hex, backgroundImage: color.swatch ? 'url(' + color.swatch + ')' : undefined, backgroundSize: 'cover' }"><AppIcon v-if="selectedColors.includes(color.code)" name="Check" :size="16" /></span><small>{{color.code}}</small></button></div><h2><span class="step-circle">2</span> Reparte las cantidades por talla</h2><p class="configurator-hint">Todo tu equipo de una vez. Indica cuántas prendas necesitas.</p><div v-for="color in chosen" :key="color.code" class="quantity-color"><div class="quantity-color-label"><i :style="{ background: color.hex, backgroundImage: color.swatch ? 'url(' + color.swatch + ')' : undefined, backgroundSize: 'cover' }" /><b>{{color.name}}</b><small>{{color.code}}</small></div><div class="size-grid"><label v-for="size in product.sizes" :key="size" :class="{unavailable:!color.sizes.includes(size)}"><span>{{size}}</span><input v-if="color.sizes.includes(size)" v-model.number="quantities[`${color.code}:${size}`]" type="number" min="0" max="10000" step="1" inputmode="numeric" placeholder="0" :aria-label="`Cantidad ${color.name}, talla ${size}`" @input="added=0" /><span v-else title="Combinación no incluida en el catálogo" class="size-unavailable">—</span></label></div></div><p v-if="!chosen.length" class="alert">Selecciona al menos un color para ver sus tallas.</p><p class="variant-note">«—» indica una combinación no incluida en el catálogo. Las opciones no representan existencias en almacén.</p><p v-if="validation" role="alert" class="field-error">{{validation}}</p><button v-if="product.source.reviewed" class="button dark full add-selection" @click="add"><AppIcon name="Plus" />Añadir a mi selección<span>{{total}} uds.</span></button><p v-else class="alert">Esta ficha está pendiente de revisión. Contacta con el equipo para confirmar las variantes.</p><div v-if="added" role="status" class="added-message"><AppIcon name="CheckCircle2" />{{added}} prendas añadidas.<NuxtLink to="/seleccion">Revisar selección <AppIcon name="ArrowRight" :size="16" /></NuxtLink></div><p class="fine-print centered">Sin pago online. Precio, disponibilidad y plazos sujetos a confirmación.</p></div></div></div><section class="technical-details"><div><span class="eyebrow">LA PRENDA, EN DETALLE</span><h2>Que todo <span class="serif-word">encaje.</span></h2><p v-for="note in product.compositionNotes" :key="note">{{note}}</p><p class="fine-print">Fuente: catálogo JHK 2026, páginas {{product.source.printedPages}}. Las medidas son aproximadas. Compara con una prenda que te siente bien.</p><a :href="product.source.supplierUrl" target="_blank" rel="noopener" class="text-link">Ficha del fabricante <AppIcon name="ExternalLink" :size="16" /></a></div><div><h3>Guía de medidas</h3><div v-if="product.measurements.length" class="table-scroll"><table class="measurements-table"><thead><tr><th>Talla</th><th v-for="key in Object.keys(product.measurements[0]?.values || {})" :key="key">{{key}}</th></tr></thead><tbody><tr v-for="row in product.measurements" :key="row.size"><th>{{row.size}}</th><td v-for="(value,key) in row.values" :key="key">{{value}}</td></tr></tbody></table></div><p v-else>Consulta las medidas en la ficha original de abajo o con nuestro equipo.</p></div></section><details class="source-details"><summary>Consultar ficha original del catálogo <AppIcon name="ChevronDown" /></summary><div class="source-images"><img v-for="src in product.sourceImages" :key="src" :src="src" alt="Ficha original JHK 2026 con tallas, colores y composición" width="1150" height="1559" loading="lazy" /></div></details><div class="product-bottom-cta"><AppIcon name="Shirt" :size="28" /><div><h3>¿Le ponemos vuestra firma?</h3><p>Podrás añadir tu logo y pedir personalización al enviar la selección.</p></div><NuxtLink to="/personalizacion" class="text-link">Ver opciones <AppIcon name="ArrowUpRight" /></NuxtLink></div></div></template>
